import * as THREE from './vendor/three.module.js';
// Depth-based contact shading and filmic display transform. No save/simulation state.
export class Graphics {
 constructor(view){this.v=view;this.enabled=true;this.target=new THREE.WebGLRenderTarget(1,1,{type:THREE.HalfFloatType,minFilter:THREE.LinearFilter,magFilter:THREE.LinearFilter,depthBuffer:true});this.target.depthTexture=new THREE.DepthTexture(1,1,THREE.UnsignedIntType);this.target.samples=Math.min(4,view.renderer.capabilities.maxSamples);this.scene=new THREE.Scene();this.camera=new THREE.OrthographicCamera(-1,1,1,-1,0,1);this.material=new THREE.ShaderMaterial({depthTest:false,depthWrite:false,toneMapped:false,uniforms:{color:{value:this.target.texture},depth:{value:this.target.depthTexture},inverseProjection:{value:view.camera.projectionMatrixInverse},resolution:{value:new THREE.Vector2(1,1)},projectionScale:{value:1},exposure:{value:1},strength:{value:.9}},vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.,1.);}',fragmentShader:`
precision highp float;
uniform sampler2D color,depth;uniform mat4 inverseProjection;uniform vec2 resolution;uniform float projectionScale,exposure,strength;varying vec2 vUv;
vec3 positionAt(vec2 uv){float d=texture2D(depth,uv).r;vec4 p=inverseProjection*vec4(uv*2.-1.,d*2.-1.,1.);return p.xyz/p.w;}
vec3 filmic(vec3 x){x*=exposure;return clamp((x*(2.51*x+.03))/(x*(2.43*x+.59)+.14),0.,1.);}
void main(){vec3 col=texture2D(color,vUv).rgb;float d=texture2D(depth,vUv).r;float occ=0.;if(d<.99998){vec3 p=positionAt(vUv),normal=normalize(cross(dFdx(p),dFdy(p)));float r=clamp(.8*projectionScale/max(1.,-p.z),2./resolution.y,.022);float phase=fract(sin(dot(floor(vUv*resolution/2.),vec2(12.9898,78.233)))*43758.5453)*6.28318;
for(int i=0;i<16;i++){float f=float(i)+.5,a=f*2.39996+phase;vec2 off=vec2(cos(a)*resolution.y/resolution.x,sin(a))*r*sqrt(f/16.);vec2 uv=clamp(vUv+off,vec2(.001),vec2(.999));vec3 delta=positionAt(uv)-p;float dist=length(delta);occ+=max(0.,dot(normal,delta/max(.001,dist))-.12)*(1.-smoothstep(.15,2.8,dist));}occ=clamp(occ/16.*strength,0.,.38);}
col*=1.-occ;col=filmic(col);float luminance=dot(col,vec3(.2126,.7152,.0722));col=mix(vec3(luminance),col,.94);gl_FragColor=vec4(pow(col,vec3(1./2.2)),1.);}`});this.scene.add(new THREE.Mesh(new THREE.PlaneGeometry(2,2),this.material));}
 resize(){const r=this.v.renderer,size=r.getDrawingBufferSize(new THREE.Vector2());this.target.setSize(size.x,size.y);this.material.uniforms.resolution.value.copy(size)}
 render(){const v=this.v;if(!this.enabled){v.renderer.setRenderTarget(null);v.renderer.render(v.scene,v.camera);return}this.material.uniforms.inverseProjection.value=v.camera.projectionMatrixInverse;this.material.uniforms.projectionScale.value=v.camera.projectionMatrix.elements[5];this.material.uniforms.exposure.value=v.renderer.toneMappingExposure;v.renderer.setRenderTarget(this.target);v.renderer.render(v.scene,v.camera);v.renderer.setRenderTarget(null);v.renderer.render(this.scene,this.camera)}
}
